    Bug 1951368 - Fix row count in "Search Messages…" after deleting. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D240137

diff --git a/mailnews/base/src/nsMsgSearchDBView.cpp b/mailnews/base/src/nsMsgSearchDBView.cpp
index 5d8ac2d6fb2..d7a7f192a71 100644
--- a/mailnews/base/src/nsMsgSearchDBView.cpp
+++ b/mailnews/base/src/nsMsgSearchDBView.cpp
@@ -1413,7 +1413,12 @@ nsMsgSearchDBView::OnDeleteCompleted(bool aSucceeded) {
   if (m_deletingRows) {
     SetSuppressChangeNotifications(false);
     m_deletingRows = false;
-    if (mTree) mTree->Invalidate();
+    if (mTree) {
+      mTree->BeginUpdateBatch();
+      // This seems to be the easiest way to update the row count of the
+      // XUL tree and invalidate it.
+      mTree->EndUpdateBatch();
+    }
     if (mJSTree) mJSTree->Invalidate();
   }
   return NS_OK;
